from __future__ import annotations
import json
from pathlib import Path
from taf.ul.ue.sim.env_setup.utils.enums import DevicesNames


def validate_full_rack_pairs(config: dict) -> None:
    primary = secondary = 0
    for host_config in config.values():
        for bts_type in [DevicesNames.ENB, DevicesNames.GNB]:
            for bts in host_config.get(bts_type, {}):
                if bts.get("primary", False):
                    primary += 1
                if bts.get("secondary", False):
                    secondary += 1
    assert primary == secondary, (
        "Full-rack configuration detected, but there are not the same number of primary and secondary BTSes."
        " Remember to add secondary BTS without SCFC."
    )


def make_sure_directory_exists(dir_path: Path) -> None:
    if dir_path.exists() is False:
        dir_path.mkdir(parents=True)


def dump_config_to_file(config: dict, f_path: Path) -> None:
    with f_path.open("w") as config_file:
        json.dump(config, config_file, indent=4)


def load_file(f_path: Path, remove: bool = True) -> dict:
    with f_path.open("r") as result_fd:
        result = json.load(result_fd)
    if remove is True:
        f_path.unlink()
    return result
